import { createDataSDK } from "@salesforce/sdk-data";
const HIGH_REVENUE_ACCOUNTS_QUERY = (
  /* GraphQL */
  `
	query GetHighRevenueAccounts($minRevenue: Currency) {
		uiapi {
			query {
				Account(
					where: { AnnualRevenue: { gt: $minRevenue } }
					orderBy: { AnnualRevenue: { order: DESC } }
					first: 50
				) {
					edges {
						node {
							Id
							Name {
								value
							}
							AnnualRevenue {
								value
							}
							Industry {
								value
							}
							Website {
								value
							}
						}
					}
				}
			}
		}
	}
`
);
async function getHighRevenueAccounts(variables) {
  const data = await createDataSDK();
  const response = await data.graphql?.({ query: HIGH_REVENUE_ACCOUNTS_QUERY, variables });
  if (response?.errors?.length) {
    const errorMessages = response.errors.map((e) => e.message).join("; ");
    throw new Error(`GraphQL Error: ${errorMessages}`);
  }
  return response?.data?.uiapi?.query?.Account?.edges?.map((edge) => edge?.node) || [];
}
export {
  getHighRevenueAccounts
};
